<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { hotelApi } from '../../api'
import { errorMessage } from '../../api/client'
import DateHeatmap from '../../components/DateHeatmap.vue'
import MediaImage from '../../components/MediaImage.vue'
import ResourceImagePicker from '../../components/ResourceImagePicker.vue'
import StatusTag from '../../components/StatusTag.vue'
import type { PartnerResource } from '../../types'
import { automaticNetworkMedia, MEDIA_LIBRARY } from '../../utils/productMedia'

const route = useRoute()
const items = ref<PartnerResource[]>([])
const loading = ref(false)
const switchingId = ref<number | null>(null)
const selected = ref<PartnerResource | null>(null)
const detailVisible = ref(false)
const selectedDate = ref('')
const viewMode = ref<'cards' | 'list'>('cards')
const savingMedia = ref(false)
const visibleItems = computed(() => selectedDate.value ? items.value.filter((item) => item.available_date === selectedDate.value) : items.value)

function resourceMedia(row: PartnerResource) {
  if (row.image_url) return { ...MEDIA_LIBRARY.city, id: `resource-${row.id}`, url: row.image_url, source: row.image_source || '商户图片', source_url: row.image_attribution || row.image_url }
  const text = `${row.resource_name} ${row.category} ${row.description}`.toLowerCase()
  const fallback = /博物馆|良渚|丝绸|美术|展览/.test(text) ? MEDIA_LIBRARY.liangzhuMuseum
    : /西湖|湖滨/.test(text) ? MEDIA_LIBRARY.westLake
      : /运河|拱宸/.test(text) ? MEDIA_LIBRARY.gongchen
        : /西溪|湿地|自然/.test(text) ? MEDIA_LIBRARY.xixi
          : /茶|龙井/.test(text) ? MEDIA_LIBRARY.longjing
            : /灵隐/.test(text) ? MEDIA_LIBRARY.lingyin
              : /乐园|宋城|游乐/.test(text) ? MEDIA_LIBRARY.songcheng
                : /动漫|动画/.test(text) ? MEDIA_LIBRARY.animationMuseum
                  : /攀岩|运动|卡丁车/.test(text) ? MEDIA_LIBRARY.climbing
                    : /演出|音乐|剧场/.test(text) ? MEDIA_LIBRARY.performance
                      : /美食|餐|咖啡/.test(text) ? MEDIA_LIBRARY.warmFood
                        : MEDIA_LIBRARY.city
  return automaticNetworkMedia(`${row.resource_name} ${row.address || '杭州'} ${row.category || ''}`, fallback.kind)
}
function session(row: PartnerResource) { return row.start_time && row.end_time ? `${row.start_time.slice(0, 5)} – ${row.end_time.slice(0, 5)}` : '预约后确认时间' }
function openDetails(row: PartnerResource) { selected.value = row; detailVisible.value = true }
async function load() { loading.value = true; try { items.value = (await hotelApi.resources()).data; const focus = items.value.find((item) => item.id === Number(route.query.focus)); if (focus) openDetails(focus) } catch (error) { ElMessage.error(errorMessage(error)) } finally { loading.value = false } }
async function toggle(row: PartnerResource, enabled: boolean) { const previous = row.package_enabled; row.package_enabled = enabled; switchingId.value = row.id; try { const response = await hotelApi.toggleResourcePackage(row.id, enabled); row.package_enabled = response.data.package_enabled; ElMessage.success(row.package_enabled ? '已加入可组包资源' : '已暂停组包') } catch (error) { row.package_enabled = previous; ElMessage.error(errorMessage(error)) } finally { switchingId.value = null } }
async function saveMedia() { if (!selected.value) return; savingMedia.value = true; try { const response = await hotelApi.updateResourceMedia(selected.value.id, { image_url: selected.value.image_url || '', image_source: selected.value.image_source || '', image_attribution: selected.value.image_attribution || '' }); selected.value = response.data; const index = items.value.findIndex((item) => item.id === response.data.id); if (index >= 0) items.value[index] = response.data; ElMessage.success('资源图片已更新') } catch (error) { ElMessage.error(errorMessage(error)) } finally { savingMedia.value = false } }
onMounted(load)
</script>

<template>
  <div class="page-head"><div><div class="eyebrow">合作资源</div><h1>合作资源池</h1><p>按日期查看合作体验；点击资源可在中央窗口查看完整内容。</p></div><div class="header-actions"><el-radio-group v-model="viewMode" class="view-mode-switch" size="small" aria-label="资源展示方式"><el-radio-button label="cards">卡片</el-radio-button><el-radio-button label="list">列表</el-radio-button></el-radio-group><el-button plain @click="load">刷新</el-button></div></div>
  <div class="resource-toolbar panel"><DateHeatmap v-model="selectedDate" :items="items" quantity-key="remaining_capacity" label="体验日期" /></div>
  <div v-if="viewMode === 'cards'" v-loading="loading" class="resource-grid"><article v-for="row in visibleItems" :key="row.id" class="resource-card" @click="openDetails(row)"><MediaImage :media="resourceMedia(row)" aspect="card" /><div class="resource-card__body"><div class="resource-card__top"><span>{{ row.category || '在地体验' }}</span><strong :class="row.remaining_capacity <= 5 ? 'warning-text' : ''">余 {{ row.remaining_capacity }}</strong></div><h2>{{ row.resource_name }}</h2><p>{{ row.merchant_name || '合作商户' }} · {{ row.available_date }} · {{ session(row) }}</p><div class="resource-tags"><span v-if="row.indoor">室内</span><span v-if="row.suitable_crowds">适合 {{ row.suitable_crowds }}</span></div><div class="resource-card__bottom"><span>¥{{ row.settlement_price }} 结算</span><label @click.stop><el-switch :model-value="row.package_enabled" size="small" :loading="switchingId === row.id" @change="toggle(row, Boolean($event))" /><b>{{ row.package_enabled ? '可组包' : '未组包' }}</b></label></div></div></article></div>
  <div v-else class="panel table-wrap"><el-table v-loading="loading" :data="visibleItems" style="width:100%" @row-click="openDetails"><el-table-column prop="resource_name" label="资源名称" min-width="220"><template #default="{row}"><strong>{{ row.resource_name }}</strong><div class="muted">{{ row.merchant_name || '合作商户' }}</div></template></el-table-column><el-table-column prop="available_date" label="日期" width="120" /><el-table-column label="场次" width="145"><template #default="{row}">{{ session(row) }}</template></el-table-column><el-table-column label="余量" width="90"><template #default="{row}"><strong :class="row.remaining_capacity <= 5 ? 'warning-text' : ''">{{ row.remaining_capacity }}</strong></template></el-table-column><el-table-column label="结算价" width="100"><template #default="{row}">¥{{ row.settlement_price }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><StatusTag :status="row.status" /></template></el-table-column><el-table-column label="组包" width="132"><template #default="{row}"><div class="switch-cell" @click.stop><el-switch :model-value="row.package_enabled" :loading="switchingId === row.id" @change="toggle(row, Boolean($event))" /><span>{{ row.package_enabled ? '可组包' : '未组包' }}</span></div></template></el-table-column><el-table-column label="详情" width="80"><template #default="{row}"><el-button link type="primary" @click.stop="openDetails(row)">查看</el-button></template></el-table-column></el-table></div>
  <div v-if="!loading && !visibleItems.length" class="panel empty-state">这一天暂时没有合作资源。</div>
  <el-dialog v-model="detailVisible" :title="selected?.resource_name || '资源详情'" width="min(94vw, 880px)" top="7vh" destroy-on-close><div v-if="selected" class="resource-detail"><MediaImage :media="resourceMedia(selected)" aspect="hero" /><div class="resource-detail__content"><div class="detail-kicker">{{ selected.category || '在地体验' }} · {{ selected.merchant_name || '合作商户' }}</div><div class="detail-title"><div><h2>{{ selected.resource_name }}</h2><p>{{ selected.description || '合作商户维护的在地体验内容。' }}</p></div><strong :class="selected.remaining_capacity <= 5 ? 'warning-text' : ''">余 {{ selected.remaining_capacity }}</strong></div><div class="detail-stat-grid"><div><span>日期</span><b>{{ selected.available_date }}</b></div><div><span>时间</span><b>{{ session(selected) }}</b></div><div><span>结算价</span><b>¥{{ selected.settlement_price }}</b></div><div><span>已被引用</span><b>{{ selected.referenced_product_count }} 款产品</b></div></div><div class="detail-rows"><div><span>地点</span><strong>{{ selected.address || '以预约信息为准' }}</strong></div><div><span>适合人群</span><strong>{{ selected.suitable_crowds || '以商家说明为准' }}</strong></div><div><span>预约提示</span><strong>{{ selected.booking_notice || '请在出发前与商家确认' }}</strong></div><div><span>组包状态</span><strong>{{ selected.package_enabled ? '已允许酒店组包' : '当前未允许酒店组包' }}</strong></div></div><div class="resource-media-edit"><span>展示图片</span><ResourceImagePicker v-model="selected.image_url" v-model:source="selected.image_source" v-model:attribution="selected.image_attribution" :query="`${selected.resource_name} ${selected.address || '杭州'}`" /><el-button size="small" type="primary" :loading="savingMedia" @click="saveMedia">保存图片</el-button></div></div></div><template #footer><el-button @click="detailVisible=false">关闭</el-button><el-button v-if="selected" type="primary" plain @click="toggle(selected, !selected.package_enabled)">{{ selected.package_enabled ? '暂停组包' : '允许组包' }}</el-button></template></el-dialog>
</template>

<style scoped>
.header-actions,.resource-toolbar{display:flex;align-items:center;gap:10px}.header-actions{justify-content:flex-end;flex-wrap:wrap}.view-mode-switch{order:-1}.resource-toolbar{margin-bottom:12px;padding:10px}.resource-toolbar :deep(.date-heatmap){width:100%;border:0;padding:0;background:transparent}.resource-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(310px,1fr));gap:10px}.resource-card{display:grid;grid-template-columns:104px minmax(0,1fr);min-height:146px;overflow:hidden;border:1px solid var(--line);border-radius:12px;background:var(--paper);cursor:pointer;transition:transform .2s ease,border-color .2s ease,box-shadow .2s ease}.resource-card:hover{transform:translateY(-2px);border-color:#b9c8c2;box-shadow:0 12px 26px rgba(20,25,23,.08)}.resource-card :deep(.media-image){height:100%;min-height:146px;aspect-ratio:auto;border-radius:0}.resource-card__body{min-width:0;padding:11px}.resource-card__top,.resource-card__bottom,.detail-title{display:flex;align-items:center;justify-content:space-between;gap:10px}.resource-card__top>span,.detail-kicker{color:var(--muted);font-size:10px}.resource-card__top>strong{font-family:var(--font-mono);font-size:14px}.resource-card h2{overflow:hidden;margin:7px 0 4px;font-size:15px;text-overflow:ellipsis;white-space:nowrap}.resource-card p{overflow:hidden;margin:0;color:var(--muted);font-size:10px;text-overflow:ellipsis;white-space:nowrap}.resource-tags{display:flex;flex-wrap:wrap;gap:5px;margin:8px 0}.resource-tags span{padding:3px 6px;border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:9px}.resource-card__bottom{padding-top:8px;border-top:1px solid var(--line);color:var(--ink);font-family:var(--font-mono);font-size:11px}.resource-card__bottom label,.switch-cell{display:flex;align-items:center;gap:6px;font-family:inherit}.resource-card__bottom b,.switch-cell span{color:var(--muted);font-size:10px;font-weight:500}.resource-detail{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:18px}.resource-detail>:first-child{min-height:400px;border-radius:10px}.resource-detail__content{min-width:0}.detail-kicker{margin-top:4px;letter-spacing:.08em}.detail-title{align-items:flex-start;margin:9px 0 15px}.detail-title h2{margin:0 0 7px;font-size:22px;letter-spacing:-.3px}.detail-title p{margin:0;color:var(--muted);font-size:13px;line-height:1.65}.detail-title>strong{flex:0 0 auto;font-family:var(--font-mono);font-size:16px}.detail-stat-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.detail-stat-grid div{padding:10px;border:1px solid var(--line);border-radius:9px;background:var(--panel-soft)}.detail-stat-grid span{display:block;color:var(--muted);font-size:10px}.detail-stat-grid b{display:block;margin-top:5px;font-family:var(--font-mono);font-size:12px}.detail-rows{margin-top:10px;border-top:1px solid var(--line)}.detail-rows div{display:grid;grid-template-columns:78px 1fr;gap:10px;padding:8px 0;border-bottom:1px solid var(--line)}.detail-rows span{color:var(--muted);font-size:11px}.detail-rows strong{font-size:12px;font-weight:550;line-height:1.55}.resource-media-edit{margin-top:12px;padding-top:10px;border-top:1px solid var(--line)}.resource-media-edit>span{display:block;margin-bottom:7px;color:var(--muted);font-size:11px}.resource-media-edit>.el-button{margin-top:8px}@media(max-width:760px){.header-actions{justify-content:flex-start;margin-top:12px}.resource-toolbar{align-items:stretch;flex-direction:column}.resource-grid{grid-template-columns:1fr}.resource-card{grid-template-columns:96px minmax(0,1fr);min-height:128px}.resource-card :deep(.media-image){min-height:128px}.resource-card__body{padding:9px}.resource-detail{grid-template-columns:1fr}.resource-detail>:first-child{min-height:190px;height:190px}.detail-title h2{font-size:19px}}
</style>
